import { request as httpRequest } from "node:http";
import { request as httpsRequest } from "node:https";
import { URL } from "node:url";
import { ProxyAgent } from "proxy-agent";
class BufferedHttpResponse {
    statusCode;
    headers;
    bodyText;
    constructor(statusCode, headers, bodyText) {
        this.statusCode = statusCode;
        this.headers = headers;
        this.bodyText = bodyText;
    }
    async text() {
        return this.bodyText;
    }
    async json() {
        return JSON.parse(this.bodyText);
    }
}
export class DefaultHttpClient {
    proxyConfig;
    cookies = new Map();
    defaultHeaders = {
        "Accept-Language": "en-US",
    };
    constructor(proxyConfig) {
        this.proxyConfig = proxyConfig;
        if (proxyConfig?.preventKeepingConnectionsAlive) {
            this.defaultHeaders.Connection = "close";
        }
    }
    setCookie(name, value) {
        this.cookies.set(name, value);
    }
    async get(url) {
        return this.request("GET", url);
    }
    async postJson(url, body) {
        return this.request("POST", url, JSON.stringify(body), {
            "Content-Type": "application/json",
        });
    }
    buildCookieHeader() {
        if (this.cookies.size === 0) {
            return undefined;
        }
        return [...this.cookies.entries()].map(([name, value]) => `${name}=${value}`).join("; ");
    }
    async request(method, urlString, body, extraHeaders = {}) {
        const url = new URL(urlString);
        const cookieHeader = this.buildCookieHeader();
        const headers = { ...this.defaultHeaders, ...extraHeaders };
        if (cookieHeader) {
            headers.cookie = cookieHeader;
        }
        if (body) {
            headers["Content-Length"] = Buffer.byteLength(body).toString();
        }
        const proxyUrl = this.proxyConfig?.toRequestsDict()[url.protocol === "https:" ? "https" : "http"];
        const agent = proxyUrl ? new ProxyAgent({ getProxyForUrl: () => proxyUrl }) : undefined;
        const requestFn = url.protocol === "https:" ? httpsRequest : httpRequest;
        return new Promise((resolve, reject) => {
            const req = requestFn(url, { agent, headers, method }, (response) => {
                const chunks = [];
                response.on("data", (chunk) => {
                    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
                });
                response.on("end", () => {
                    resolve(new BufferedHttpResponse(response.statusCode ?? 0, response.headers, Buffer.concat(chunks).toString("utf8")));
                });
            });
            req.on("error", reject);
            if (body) {
                req.write(body);
            }
            req.end();
        });
    }
}
